const CFG = {"business":"Northlight Studio","ownerName":"Sam","mailbox":"billing@northlight.studio","emailMode":"demo","testMode":true,"currency":"USD","paymentLink":"https://pay.northlight.studio/invoices","aiModel":"claude-opus-5-5"};
// Shared helpers, added to the top of every Code node by build.js. CFG comes from config.json.
const today = (typeof $now !== 'undefined' && $now && $now.toISODate) ? $now.toISODate() : new Date().toISOString().slice(0, 10);
const nowIso = new Date().toISOString();
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const DAYS = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
const isDate = (s) => /^\d{4}-\d{2}-\d{2}$/.test(String(s || ''));
const toUTC = (s) => { const [y, m, d] = String(s).split('-').map(Number); return Date.UTC(y, m - 1, d); };
const addDays = (s, n) => new Date(toUTC(s) + n * 86400000).toISOString().slice(0, 10);
const daysBetween = (a, b) => Math.round((toUTC(b) - toUTC(a)) / 86400000); // b - a
const weekday = (s) => DAYS[new Date(toUTC(s)).getUTCDay()];
const fmtDate = (s) => (isDate(s) ? `${MONTHS[Number(s.slice(5, 7)) - 1]} ${Number(s.slice(8, 10))}` : '');
const money = (n, cur) => {
  const v = Number(n) || 0;
  try { return new Intl.NumberFormat('en-US', { style: 'currency', currency: cur || CFG.currency, maximumFractionDigits: 0 }).format(v); }
  catch { return '$' + Math.round(v).toLocaleString('en-US'); }
};
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const slug = (s) => String(s || 'client').toLowerCase().replace(/[^a-z0-9]+/g, '').slice(0, 20) || 'client';
// emailMode "demo": nothing leaves the machine, emails land in the Mailbox table, so real addresses are shown.
// emailMode "real" + testMode: every client email goes to a plus-address of your own inbox (you+acmedental@gmail.com).
const DEMO = CFG.emailMode === 'demo';
const recipient = (email, company) => {
  if (DEMO || !CFG.testMode) return email;
  const [user, domain] = CFG.mailbox.split('@');
  return `${user}+${slug(company)}@${domain}`;
};
const tag = (inv) => `[${inv}]`;

// The owner's own voice, carried into English. Every prompt that writes text includes this.
const VOICE = `Write in ${CFG.ownerName}'s own voice, in English. This is how he writes:
- Connected, the way he talks: one flowing thought where each sentence comes out of the one before, joined with "and", "but", "so", "because", "even if". Not a string of short separate sentences, and not many full stops.
- Natural order: the situation, then the reason, then how he feels about it, then the ask.
- Warm and direct: a quick human check-in at the start ("Hey Rachel, hope you're doing well"), plain everyday words, polite softeners like "if that's okay", "sorry to chase you on this", "honestly".
- Fair: he admits the other side before his point ("I totally get that things get busy, but...").
- He softens instead of accusing: "it might have slipped through", "maybe it got buried in the inbox".
- He says the feeling plainly when it matters: "I'd really appreciate it", "I really need this sorted".
- He ends with an open question or an offer to help, never a polished one-liner ("and if anything's holding it up just tell me and I'll sort it out with you").
- Words like "really", "honestly", "totally" show up now and then, never all together and not in every message.
- Never: bookish or corporate words (kindly, per my last email, please be advised, valued, leverage), em dashes, exclamation marks, emoji, or a wise-sounding closing line.`;

// Picks the invoices whose next step is due today and asks the AI to write each email.
const rows = $input.all().map((i) => i.json).filter((r) => r.invoice_no);

const TONE = {
  heads_up: 'A friendly heads-up a few days before the due date. Light and helpful, no pressure. Ask them to say if they need anything (a PO number, a different format).',
  friendly: 'The invoice is due or a few days overdue. Warm and polite. Assume it slipped through the cracks. Ask when they expect to pay.',
  clear: 'About a week or more overdue. Still polite, but clear and direct about the amount and how late it is. Ask for a payment date.',
  firm: 'Two weeks or more overdue, after several reminders. Firm and professional, never threatening. Ask them to pay or reply with a date this week, and offer a quick call if something is wrong.',
  broken_promise: 'The client promised to pay by a date that has now passed. Polite. Mention their promise and the date specifically, and ask for an updated date.',
  escalate: 'This is an INTERNAL note to the business owner, not to the client. Several reminders got no payment. In 2-3 sentences summarize the situation and suggest the next human step, such as a phone call.',
};

const SYSTEM = `You write payment reminder emails for ${CFG.business}, sent as ${CFG.ownerName}.

${VOICE}

Rules for these emails:
- Plain text only, no markdown, 50 to 120 words for the body, and a new line is fine where he would pause.
- Always include the invoice number, the amount, the due date and the payment link.
- Never threaten, and never mention legal action, late fees, collections or credit. No guilt-tripping.
- Greet the contact by first name if given, otherwise "Hey there".
- Unless the stage says otherwise, end by asking when they expect to pay, because replies are read and handled.
- Sign off with "Thanks," then "${CFG.ownerName}" on the next line.
- For an internal note to the owner, write it the way he'd jot a note to himself: plain and connected, no greeting and no sign-off.
- subject: short and specific (3 to 8 words), in his plain style. Don't add the invoice tag in brackets, it's added automatically.`;

const SCHEMA = {
  type: 'object',
  properties: { subject: { type: 'string' }, body: { type: 'string' } },
  required: ['subject', 'body'],
  additionalProperties: false,
};

const due = rows.filter((r) => ['unpaid', 'promised'].includes(r.status) && isDate(r.next_action) && r.next_action <= today);
if (!due.length) return [];

return due.map((r) => {
  const late = daysBetween(r.due_date, today); // positive = overdue
  const sent = Number(r.reminders_sent) || 0;
  let stage;
  if (r.status === 'promised') stage = 'broken_promise';
  else if (sent >= 4) stage = 'escalate';
  else if (late < 0) stage = 'heads_up';
  else if (late < 7) stage = 'friendly';
  else if (late < 14) stage = 'clear';
  else stage = 'firm';

  const facts = `Invoice: ${r.invoice_no}
Client company: ${r.client_company}
Contact name: ${r.client_name || '(unknown)'}
Amount: ${money(r.amount, r.currency)}
Issued: ${fmtDate(r.issue_date)}
Due: ${fmtDate(r.due_date)} (${late > 0 ? late + ' days overdue' : late === 0 ? 'due today' : 'due in ' + -late + ' days'})
Reminders already sent: ${sent}
${r.status === 'promised' ? `They promised to pay by: ${fmtDate(r.promised_date)} (${weekday(r.promised_date)})\n` : ''}Payment link: ${r.invoice_link || CFG.paymentLink}
Today: ${fmtDate(today)} (${weekday(today)})

Stage and tone: ${TONE[stage]}`;

  return {
    json: {
      invoice: r,
      stage,
      late,
      aiBody: {
        model: CFG.aiModel,
        max_tokens: 4000,
        system: SYSTEM,
        messages: [{ role: 'user', content: facts }],
        output_config: { effort: 'low', format: { type: 'json_schema', schema: SCHEMA } },
        fallbacks: 'default',
      },
    },
  };
});

